// A. One requirement per statement, each traced to its source.
const FRS = [
  {
    id: 'FR-1',
    source: 'UC-02',
    text: 'The system shall display the free 15-minute slots of a selected doctor for the next 14 days.',
  },
  {
    id: 'FR-2',
    source: 'BR-03',
    text: 'The system shall refuse a booking from a patient who already holds 2 future appointments.',
  },
  {
    id: 'FR-3',
    source: 'BR-02',
    text: 'The system shall require prepayment through VNPay when the patient has 3 no-shows in the last 90 days.',
  },
  { id: 'FR-4', source: 'BR-04', text: 'The system shall calculate the visit fee as the service fee plus 10% VAT.' },
  {
    id: 'FR-5',
    source: 'BR-01',
    text: 'The system shall allow a patient to cancel an appointment free of charge up to 2 hours before it starts.',
  },
  {
    id: 'FR-6',
    source: 'UC-17',
    text: 'The system shall send an SMS reminder to the patient 24 hours before each appointment.',
  },
  {
    id: 'FR-7',
    source: 'UC-13',
    text: 'The system shall mark an appointment as a no-show when the patient has not checked in 15 minutes after its start.',
  },
  {
    id: 'FR-8',
    source: 'UC-11',
    text: 'The system shall store the prescription code returned by the National e-Prescription System with each prescription.',
  },
  {
    id: 'FR-9',
    source: 'UC-12',
    text: 'The system shall let a receptionist record the arrival time of a patient with a booked appointment.',
  },
];

// B. Each one: action, measure, unit, conditions.
const NFRS = {
  performance: 'The system shall display the free slots of a doctor within 2 seconds for 95% of requests with 200 concurrent users.',
  availability: 'The system shall be available 99.5% of the time between 06:00 and 22:00 every day, excluding announced maintenance.',
  security: 'The system shall allow only the doctor of an appointment and the patient to view its visit notes, and shall lock an account for 15 minutes after 5 failed login attempts.',
  usability: 'The system shall let 90% of first-time patients complete a booking within 3 minutes without help.',
};

// C. Planguage for the usability requirement.
const PLANGUAGE = {
  TAG: 'Booking.Usability',
  AMBITION: 'First-time patients book without help.',
  SCALE: 'Minutes from opening the app to the confirmation screen for a first-time patient.',
  METER: 'Usability test with 20 first-time patients aged 18–70, 90th percentile.',
  GOAL: '3 minutes',
  STRETCH: '2 minutes',
};

// E. Context in section 2, features in 3, data in 4, interfaces in 5, quality in 6.
const SRS_SECTION = {
  S1: '2.2 User classes and characteristics',
  S2: '2.3 Operating environment',
  S3: '2.4 Design and implementation constraints',
  S4: '2.5 Assumptions and dependencies',
  S5: '5.2 Software interfaces',
  S6: '6 Quality attributes',
  S7: '4 Data requirements',
  S8: '3 System features',
  S9: '1.3 Project scope',
};

